llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Disopyramide, which shares the phenyl/2-pyridyl central carbon and basic amine motif, has absolute oral bioavailability of 73% in humans after oral vs i.v. dosing, supporting F >=20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Doxylamine, a phenyl/pyridyl tertiary-amine analogue, showed 50% oral bioavailability in normal subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Imidafenacin, with a similar central quaternary carbon bearing aryl groups and a basic heterocycle, has absolute oral bioavailability of 57.8% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Bepotastine, a pyridyl-containing piperidine drug, has >80% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Fexofenadine, despite transporter/efflux liabilities, has absolute oral bioavailability of 41% in humans, supporting F >=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Terfenadine has <5% oral bioavailability, but this low value is due to extensive first-pass metabolism as a prodrug and is weak contradictory evidence because the query lacks the metabolically labile tert-butylphenyl motif.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "The R-enantiomer of oxybutynin has estimated oral bioavailability of 6.7%, but this reflects first-pass metabolism of the ester/alkyne scaffold absent in the query, so it is weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query's phenyl/2-pyridyl tertiary-carbinol basic amine scaffold is most closely mirrored by disopyramide, doxylamine, imidafenacin, bepotastine, and fexofenadine, all with human oral F values of 41-80% (>=20%). The low-F analogues terfenadine and oxybutynin owe their poor F to specific first-pass/prodrug liabilities absent in the query. Therefore predict high F, with moderate confidence.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the query molecule",
    "Morgan similarities to evidence molecules are low (0.24-0.33), limiting quantitative transferability",
    "First-pass metabolism and transporter-mediated disposition of the query are unknown",
    "The fully ionized basic center at pH 7.4 may affect permeability, but the prior is low confidence and not supported by the analogue data"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

